ALTER TABLE proposed_actions DROP CONSTRAINT proposed_actions_kind_check;
ALTER TABLE proposed_actions ADD CONSTRAINT proposed_actions_kind_check CHECK(kind IN ('summary','crm_note','message','task','listing_update','question'));
ALTER TABLE commitments ADD COLUMN source_action_id text UNIQUE;
ALTER TABLE commitments ADD CONSTRAINT commitments_source_action_fk FOREIGN KEY(workspace_id,source_action_id) REFERENCES proposed_actions(workspace_id,id);
ALTER TABLE tasks ADD COLUMN calendar_schedule jsonb;
ALTER TABLE appointments ADD CONSTRAINT appointments_workspace_id_unique UNIQUE(workspace_id,id);
CREATE TABLE work_products (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), kind text NOT NULL CHECK(kind IN ('seller_preparation','appointment_briefing')), agent_id text NOT NULL, client_id text, property_id text, appointment_id text, source_conversation_id text, source_package_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,agent_id) REFERENCES agents(workspace_id,id), FOREIGN KEY(workspace_id,client_id) REFERENCES clients(workspace_id,id), FOREIGN KEY(workspace_id,property_id) REFERENCES properties(workspace_id,id), FOREIGN KEY(workspace_id,appointment_id) REFERENCES appointments(workspace_id,id), FOREIGN KEY(workspace_id,source_conversation_id) REFERENCES conversations(workspace_id,id), FOREIGN KEY(workspace_id,source_package_id) REFERENCES work_packages(workspace_id,id));
CREATE TABLE work_product_versions (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), product_id text NOT NULL, version integer NOT NULL CHECK(version > 0), edit_revision integer NOT NULL DEFAULT 0 CHECK(edit_revision >= 0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), origin text NOT NULL CHECK(origin IN ('sample','openai')), content jsonb NOT NULL, original_content jsonb NOT NULL, snapshot jsonb NOT NULL, request_id text NOT NULL, request_fingerprint text NOT NULL, request_metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewer text, review_input_revision integer, pdf_base64 text, pdf_sha256 text, UNIQUE(workspace_id,id), UNIQUE(workspace_id,product_id,version), UNIQUE(workspace_id,request_id), UNIQUE(workspace_id,product_id,id), FOREIGN KEY(workspace_id,product_id) REFERENCES work_products(workspace_id,id), CHECK((status='pending' AND reviewed_at IS NULL AND reviewer IS NULL) OR (status IN ('approved','rejected') AND reviewed_at IS NOT NULL AND reviewer IS NOT NULL)), CHECK((status='approved' AND pdf_base64 IS NOT NULL AND pdf_sha256 IS NOT NULL) OR (status<>'approved' AND pdf_base64 IS NULL AND pdf_sha256 IS NULL)));
CREATE TABLE work_product_audits (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES workspaces(id), product_id text NOT NULL, version_id text NOT NULL, event text NOT NULL CHECK(event IN ('created','edited','approved','rejected')), edit_revision integer NOT NULL CHECK(edit_revision >= 0), content jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,product_id,version_id) REFERENCES work_product_versions(workspace_id,product_id,id));
CREATE INDEX work_products_workspace_links_idx ON work_products(workspace_id,agent_id,client_id,property_id);
CREATE INDEX work_product_versions_workspace_status_idx ON work_product_versions(workspace_id,status);
CREATE INDEX work_product_audits_version_idx ON work_product_audits(workspace_id,version_id,created_at);
